export function Event({
  title = "{{title}}",
  date = "{{date}}",
  time = "{{time}}",
  category = "{{category}}",
  accent = "{{accent}}",
}) {
  const catColor = { Work: "#241430", Personal: "#a1447e", Holiday: "#b5750f" }[category] ?? "#241430";
  return (
    <article style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 340, padding: "12px 14px", borderRadius: 10, boxSizing: "border-box", display: "flex", gap: 10, boxShadow: "0 4px 12px rgba(36,20,48,.08)" }}>
      <span style={{ width: 4, borderRadius: 2, background: accent, flex: "none" }} />
      <div>
        <p style={{ margin: 0, fontWeight: 700 }}>{title}</p>
        <p style={{ margin: "4px 0 0", fontSize: 12, color: "#24143099" }}>
          <time dateTime={`${date}T${time}`}>{time}</time> &middot; <span style={{ textTransform: "uppercase", letterSpacing: ".04em", fontWeight: 700, color: catColor }}>{category}</span>
        </p>
      </div>
    </article>
  );
}
